import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

const root = process.cwd();
const marker = "GC_PHASE4H2_6_IDENTITY_SAFE_AUTOMATION_PREVIEW_V1";
const files = [
  {
    "relative": "src/server/gc-ratings/identityPreview.ts",
    "prerequisite": "GC_PHASE4H2_5_IDENTITY_PROFILE_LINK_REVIEW_V1",
    "expectedSha256": "cffc853f4b7f8e9a5e40503d525fb11b28c009d35a6b64f0f1aba88424057ec3",
    "base64": ""
  },
  {
    "relative": "src/pages/admin/integridad-ratings/identidades/preview.astro",
    "prerequisite": "GC_PHASE4H2_5_IDENTITY_PROFILE_LINK_REVIEW_V1",
    "expectedSha256": "4da99878b9db82dab16d44caec86e9331d795ecb6b21bb194a4f8cc4fe13f32e",
    "base64": ""
  }
];

function sha256(buffer) {
  return crypto.createHash('sha256').update(buffer).digest('hex');
}

const states = files.map((file) => {
  const absolute = path.join(root, file.relative);
  if (!fs.existsSync(absolute)) throw new Error(`Falta el archivo requerido: ${file.relative}`);
  const current = fs.readFileSync(absolute);
  const text = current.toString('utf8');
  if (text.includes(marker)) return { ...file, absolute, current, state: 'already' };
  if (!text.includes(file.prerequisite)) throw new Error(`${file.relative} no contiene Phase 4H.2.5. Instala primero el paquete anterior.`);
  const currentHash = sha256(current);
  if (currentHash !== file.expectedSha256) {
    throw new Error(`${file.relative} difiere de la base 4H.2.5 validada (SHA-256 ${currentHash}). No se ha modificado nada.`);
  }
  return { ...file, absolute, current, state: 'pending' };
});

if (states.every((item) => item.state === 'already')) {
  console.log('[GC Phase 4H.2.6] Ya estaba instalada; no se ha modificado nada.');
  process.exit(0);
}
if (states.some((item) => item.state === 'already')) throw new Error('Instalación parcial detectada. Restaura los archivos de 4H.2.5 antes de reintentar.');

const stamp = new Date().toISOString().replace(/[:.]/g, '-');
const backupRoot = path.join(root, '_gc_backups', `phase4h2-6-identity-safe-automation-preview-${stamp}`);
for (const item of states) {
  const backup = path.join(backupRoot, item.relative);
  fs.mkdirSync(path.dirname(backup), { recursive: true });
  fs.copyFileSync(item.absolute, backup);
}
for (const item of states) {
  const next = Buffer.from(item.base64, 'base64');
  const temporary = `${item.absolute}.gc-phase4h2-6.tmp`;
  fs.writeFileSync(temporary, next);
  fs.renameSync(temporary, item.absolute);
}

console.log('[GC Phase 4H.2.6] Preview automático seguro instalado.');
console.log(`[GC Phase 4H.2.6] Backup: ${path.relative(root, backupRoot)}`);
states.forEach((item) => console.log(`  - ${item.relative}`));
console.log('No se ha ejecutado SQL ni se ha escrito en MySQL.');
console.log('Siguiente: npm run quality && npm run build');
